/* ---------------------------------------------------------------- scopes and audience */
FIGS.scopes = (el) => {
  const A = D().auth_demos;
  let on = 0;
  const draw = () => {
    const ro = on === 0;
    html(el, `${ctl(['token: purchase:read', 'token: purchase:read purchase:write'], on)}
      <div class="card ${ro ? '' : 'af'}" style="padding:14px 18px"><div class="kpi">${ro ? A.read_only.tools_listed : A.read_write.tools_listed} tools listed<small>${ro ? esc(A.read_only.names.join(', ')) : 'all fifteen, writes included'}</small></div></div>
      ${ro ? `<div class="card bf" style="padding:14px 18px;margin-top:14px"><span class="tag bf">a write anyway: create_purchase_request</span>${pre(A.read_only_write, 120, 'font-size:16px')}<div class="small" style="margin-top:6px">Requests in Bahi afterwards: ${A.prs_after_read_only.length}.</div></div>` : ''}
      <div class="card" style="padding:14px 18px;margin-top:14px;font-size:19px"><span class="tag nt">audience</span> a token issued for another server (“rasoi-reports”), sent to the toolbox: <b>${A.audience.token_for_reports_sent_to_toolbox.status}</b>. The toolbox's own token: <b>${A.audience.token_for_toolbox_sent_to_toolbox.status}</b>.</div>`);
    onBtn(el, (i) => { on = i; draw(); });
    fitAll(el);
  };
  return { step(k) { on = k >= 2 ? 1 : 0; draw(); } };
};

