FIGS.a2astream = (el) => {
  const S = D().a2a_seq;
  const i0 = S.findIndex((e) => e.kind === 'SendStreamingMessage');
  const ev = S.slice(i0).filter((e) => e.from === 'Deccan agent' && e.to === 'Ask Rasoi' || e.kind === 'SendStreamingMessage');
  const art = ev.find((e) => e.kind === 'artifact-update');
  const res = S.slice(i0).find((e) => e.kind === 'tool result');
  html(el, `<div style="display:flex;flex-direction:column;gap:10px;height:100%">
    ${ev.map((e, i) => `<div class="card k${Math.min(i, 3)}" style="padding:10px 16px;display:grid;grid-template-columns:200px 1fr 70px;gap:12px;font-size:17px;align-items:center"><span class="chipx ${e.kind === 'artifact-update' ? 'g' : 'a'}">${esc(e.kind)}</span><span>${esc(cut(e.summary, 120))}</span><span class="tiny">${((e.t - ev[0].t) / 1000).toFixed(1)} s</span></div>`).join('')}
    <div class="card af k3" style="padding:12px 16px;flex:1"><span class="tag af">inside the artifact: Deccan's confirm_order result</span>${tpre(res ? res.payload : art.payload, 180, 'margin-top:4px;font-size:15px')}</div></div>`);
  return { step(k) { el.querySelectorAll('.k1,.k2').forEach((x) => (x.style.opacity = k >= 1 ? 1 : 0.15)); el.querySelectorAll('.k3').forEach((x) => (x.style.opacity = k >= 2 ? 1 : 0.15)); fitAll(el); } };
};

